// ====================================================================
// PCIE IP Internal Logic
// ====================================================================
reg     [3:0]   tl_rdy_conf_reg;
reg     [3:0]   tl_rdy_reg;
reg     [9:0]   tclk_deskew_cal_lock_cnt;
reg             tclk_deskew_cal_lock_flag;

reg     [9:0]   tl_power_on_rst_dly_cnt;
reg             tl_power_on_rst_dly;
wire            phy0_refclk_cmos;

wire            phy1_refclk_cmos;

wire    [1:0]   ick_ref_cml_ls_t2b_p;
wire    [1:0]   ick_ref_cml_ls_t2b_n;

always@( posedge tl_clk_user or posedge tl_power_on_rst )
begin
    if( tl_power_on_rst ) begin
        tl_power_on_rst_dly_cnt <= 10'd0;
        tl_power_on_rst_dly     <= 1'b1;
    end else begin
        tl_power_on_rst_dly_cnt <=  tl_power_on_rst_dly_cnt[9] ? tl_power_on_rst_dly_cnt : tl_power_on_rst_dly_cnt + 1'b1;
        tl_power_on_rst_dly     <= ~tl_power_on_rst_dly_cnt[9];
    end
end

assign  apb4_preset_in      = tl_power_on_rst;
 
// count the tclk dpll, delay times and wait ready
always@(posedge tl_clk_user or posedge tl_power_on_rst )
begin
    if(tl_power_on_rst) begin
        tclk_deskew_cal_lock_cnt  <= 10'd0;
    end else if(!tclk_deskew_cal_lock) begin
        tclk_deskew_cal_lock_cnt  <= 10'd0;
    end else if(tclk_deskew_cal_lock & (!tclk_deskew_cal_lock_cnt[9] )) begin
        tclk_deskew_cal_lock_cnt  <= tclk_deskew_cal_lock_cnt + 1'b1;
    end
end

always@(posedge tl_clk_user or posedge tl_power_on_rst )
begin
    if(tl_power_on_rst)begin
        tclk_deskew_cal_lock_flag <= 1'b0;
    end else begin
        tclk_deskew_cal_lock_flag <= tclk_deskew_cal_lock_cnt[9];
    end
end

// set pcie ip tl_mperst signals
always@(posedge tl_clk_user or posedge tl_power_on_rst )
begin
    if(tl_power_on_rst)begin
        tl_mperst <= 1'b1;
    end else if(!tclk_deskew_cal_lock_flag) begin
        tl_mperst <= 1'b1;
    end else  begin
        tl_mperst <= 1'b0;
    end
end

// set pcie ip tl_por signals
always@(posedge tl_clk_user or posedge tl_power_on_rst )
begin
    if(tl_power_on_rst)begin
        tl_por <= 1'b1;
    end else if(!tclk_deskew_cal_lock_flag) begin
        tl_por <= 1'b1;
    end else begin
        tl_por <= 1'b0;
    end
end

// set pcie ip tl_rst signals, need pull up after tl_rdy
always@(posedge tl_clk_user or negedge tl_rdy )
begin
    if(!tl_rdy)begin
        tl_rst  	<= 1'b1;
		tl_rdy_reg	<= 4'b0;
    end else if(!tclk_deskew_cal_lock_flag) begin
        tl_rst  	<= 1'b1;
		tl_rdy_reg	<= 4'b0;
    end else begin
        tl_rst  	<= !tl_rdy_reg[3];
		tl_rdy_reg  <= {tl_rdy_reg[2:0],1'b1};				
    end
end
// set pcie ip tl_crst signals, need pull up after tl_rdy_conf, at least 2 tl_clk cycle
always@(posedge tl_clk_user or negedge tl_rdy_conf )
begin
    if(!tl_rdy_conf)begin
        tl_crst  		<= 1'b1;
		tl_rdy_conf_reg <= 4'd0;
    end else if(!tclk_deskew_cal_lock_flag) begin
		tl_crst  		<= 1'b1;
		tl_rdy_conf_reg <= 4'd0;
	end else begin
        tl_crst  		<= !tl_rdy_conf_reg[3];
		tl_rdy_conf_reg <= {tl_rdy_conf_reg[2:0],1'b1};		
    end
end

// set pcie ip pcs_pipe_rst signals
always@(posedge tl_clk_user or posedge tl_power_on_rst )
begin
    if(tl_power_on_rst)begin
        pcs_pipe_rst <= 1'b1;
    end else if(!tclk_deskew_cal_lock_flag) begin
        pcs_pipe_rst <= 1'b1;
    end else if( !tl_rdy || !tl_rdy_conf ) begin
		pcs_pipe_rst <= 1'b1; 
    
    end else if( phy0_hxt_csr_load_done & phy1_hxt_csr_load_done ) begin
    
        pcs_pipe_rst <= 1'b0;
    end
end

// tl_clk_locked
always@(posedge tl_clk_user or posedge tl_power_on_rst )
begin
    if(tl_power_on_rst)begin
        tl_clk_locked <= 1'b0;
    end else if(tclk_deskew_cal_lock_flag & !pcs_pipe_rst & !tl_crst & !tl_rst & !tl_por & !tl_mperst ) begin
        tl_clk_locked <= 1'b1;
    end else begin
        tl_clk_locked <= 1'b0;
    end
end

