always@(posedge hxt_apb4_pclk_in or posedge tl_power_on_rst_dly)
begin
    if( tl_power_on_rst_dly ) begin
        phy1_rx0_state_ack_hold         <= 1'b0;
        phy1_rx1_state_ack_hold         <= 1'b0;
        phy1_rx2_state_ack_hold         <= 1'b0;
        phy1_rx3_state_ack_hold         <= 1'b0;
        phy1_tl_cfg_current_link_speed  <= 3'd0;
        phy1_tl_ltssm                   <= 5'd0;
    end else begin
        phy1_tl_cfg_current_link_speed  <= tl_cfg_current_link_speed[2:0];
        phy1_tl_ltssm                   <= tl_ltssm[4:0];
        phy1_rx0_state_ack_hold         <= phy1_tl_cfg_current_link_speed[2:0] == 3'd4 && phy1_tl_ltssm[4:0] == 5'hC ? 1'b1 : phy1_rx0_state_ack_hold;
        phy1_rx1_state_ack_hold         <= phy1_tl_cfg_current_link_speed[2:0] == 3'd4 && phy1_tl_ltssm[4:0] == 5'hC ? 1'b1 : phy1_rx1_state_ack_hold;
        phy1_rx2_state_ack_hold         <= phy1_tl_cfg_current_link_speed[2:0] == 3'd4 && phy1_tl_ltssm[4:0] == 5'hC ? 1'b1 : phy1_rx2_state_ack_hold;
        phy1_rx3_state_ack_hold         <= phy1_tl_cfg_current_link_speed[2:0] == 3'd4 && phy1_tl_ltssm[4:0] == 5'hC ? 1'b1 : phy1_rx3_state_ack_hold;
    end
end

assign phy1_rx_eqbk_start[0] = phy1_rx0_state_ack_hold;
assign phy1_rx_eqbk_start[1] = phy1_rx1_state_ack_hold;
assign phy1_rx_eqbk_start[2] = phy1_rx2_state_ack_hold;
assign phy1_rx_eqbk_start[3] = phy1_rx3_state_ack_hold;

