    .tx3_clk_aligner_vt_tracking_en_n        ('d0                                         ),
    .tx3_clk_aligner_bist_mode_n             ('d0                                         ),
   // rx clock aligner
    .rx3_clk_aligner_rst                     ('d0                                         ),
    .rx3_clk_aligner_phase_align_start_n     ('d0                                         ),
    .rx3_clk_aligner_en_n                    ('d0                                         ),
    .rx3_clk_aligner_phase_align_done        (                                            ),
    .rx3_clk_aligner_code_out                (                                            ),
    .rx3_clk_aligner_code_in                 ('d0                                         ),
    .rx3_clk_aligner_bypass                  ('d0                                         ),
    .rx3_clk_aligner_bist_osc_div            ('d0                                         ),
    .rx3_clk_aligner_half_in                 ('d0                                         ),
    .rx3_clk_aligner_half_out                (                                            ),
    .rx3_clk_aligner_err                     (                                            ),
    .rx3_clk_aligner_half_en                 ('d0                                         ),
    .rx3_clk_aligner_localclk_en             ('d0                                         ),
    .rx3_clk_aligner_cal_clk                 ('d0                                         ),
    .rx3_clk_aligner_bist_dto                (                                            ),
    .rx3_clk_aligner_bist_done               (                                            ),
    .rx3_clk_aligner_enc_sel                 ('d0                                         ),
    .rx3_clk_aligner_glitch_filter_en        ('d0                                         ),
    .rx3_clk_aligner_vt_tracking_en_n        ('d0                                         ),
    .rx3_clk_aligner_bist_mode_n             ('d0                                         ),
   // scan
    .dft_test_mode_n                         ('d0                                         ),
    .scan_clk                                ('d0                                         ),
    .scan_in                                 ('d0                                         ),
    .scan_out                                (                                            ),
    .scan_se                                 ('d0                                         ),
    .scan_edt_update                         ('d0                                         ),
   // bist
    .dft_jtag_tck                            ('d0                                         ),
    .dft_jtag_tdi                            ('d0                                         ),
    .dft_jtag_tms                            ('d0                                         ),
    .dft_jtag_trstn                          ('d0                                         ),
    .dft_jtag_tdo                            (                                            )
);

endmodule

module ph2_pcie_rc_subsystem_hxt_csr_load
#(  
    parameter   SIMULATION_EN       = 1'b0                                      ,
    parameter   PH2_CSR_HXT_FILE    = "hxt_csr.hex"                             
)
(
    input                                   power_on_rst_i                      ,
    output reg                              csr_load_done    = 1'b0             ,
    
    // APB4 interface
    input                                   apb4_pclk_in                        ,
    input                                   apb4_preset_in                      ,
    
    input   [3  :0]                         hxt_tx_pma_rst_i                    ,        
    input   [3  :0]                         hxt_rx_pma_rst_i                    ,      
    
    input                                   hxt_ref1_en                         ,
    input                                   hxt_ref1_float0_en                  ,
    
    input   [3  :0]                         tx_fir_start_i                      ,
    input   [3  :0]                         rx_eqbk_start_i                     ,       
    input   [3  :0]                         rx_linkeval_ack_i                   ,                                                                                                                           
    output  [3  :0]                         rx_linkeval_start_o                 ,
    input   [3  :0]                         loopback_en_i                       ,
    input   [11 :0]                         ictl_loopback_mode_i                ,   
                   
    input   [31 :0]                         master_apb4_paddr_in                ,  
    input                                   master_apb4_penable_in              , 
    input   [2  :0]                         master_apb4_pprot_in                ,     
    input                                   master_apb4_psel_in                 , 
    input   [3  :0]                         master_apb4_pstrobe_in              , 
    input   [31 :0]                         master_apb4_pwdata_in               , 
    input                                   master_apb4_pwrite_in               , 
    output  [31 :0]                         master_apb4_prdata_out              , 
    output                                  master_apb4_pready_out              ,
    output                                  master_apb4_pslverr_out             ,      
                 
    output  [31 :0]                         slave_apb4_paddr_out                ,  
    output                                  slave_apb4_penable_out              , 
    output  [2  :0]                         slave_apb4_pprot_out                ,     
    output                                  slave_apb4_psel_out                 ,
    output  [3  :0]                         slave_apb4_pstrobe_out              , 
    output  [31 :0]                         slave_apb4_pwdata_out               , 
    output                                  slave_apb4_pwrite_out               , 
    input   [31 :0]                         slave_apb4_prdata_in                , 
    input                                   slave_apb4_pready_in                ,
    input                                   slave_apb4_pslverr_in                  
);

localparam  HEX_LINENUM = 255;
localparam  CSR_NUM     = HEX_LINENUM;

localparam  DELAY_CNT   = 8'd200;

reg [31:0]  csr_data = 32'd0;
reg [31:0]  csr_addr = 32'd0;

reg         power_on_rst_ff1    = 1'b0  ;
reg         power_on_rst_ff2    = 1'b0  ;
wire        power_on_rst_nege           ;
reg         power_on_state_flag = 1'b0  ;

reg [8:0]   csr_load_cnt        = 9'd0;
reg         csr_load_work       = 1'b0;
reg         csr_load_work_ff1   = 1'b0;
reg         csr_load_work_ff2   = 1'b0;
reg         csr_load_done_r     = 1'b0;

reg         apb_write           = 1'b0  ;
reg         apb_sel             = 1'b0  ;
reg [31:0]  apb_wdata           = 32'd0 ;
reg [31:0]  apb_addr            = 32'd0 ;
reg [3:0]   apb_pstrobe         = 4'd0  ;
reg         apb_enable_r        = 1'b0  ;       
reg         apb_enable          = 1'b0  ;

reg [7:0]   apb_delay_cnt       = 8'd0  ;

// reg [63:0]  mem_csr_data[0:CSR_NUM-1]   ; /* synthesis ram_style = bram */
 
    reg [63:0]  mem_csr_data[0:CSR_NUM-1]   ; /* synthesis ram_style = none */
 
wire[31:0]  csr_addr_end                ;
reg         csr_addr_end_ff1    = 1'b0  ;
wire[31:0]  apb4_paddr_out_tmp          ;
///----------------------------------------------------------------------------
///refclk1 configer
reg [31:0]  cmn_refclk_data     = 32'd0 ;
reg [31:0]  pd_afe_cmn_data     = 32'd0 ;
///----------------------------------------------------------------------------

localparam CSR_LINENUM = HEX_LINENUM;    
integer i;
initial begin
    for(i=0;i<CSR_LINENUM;i=i+1) begin 
        mem_csr_data[i] = 64'hffffffff_ffffffff;
    end     
    $readmemh (PH2_CSR_HXT_FILE, mem_csr_data);
end      

///------------------------------------------------------------------------------------------------------------------

always @ (posedge apb4_pclk_in) begin  
    power_on_rst_ff1 <= power_on_rst_i;
    power_on_rst_ff2 <= power_on_rst_ff1;           
end 

assign power_on_rst_nege = !power_on_rst_ff1 & power_on_rst_ff2;

always @ (posedge apb4_pclk_in or posedge power_on_rst_i) begin  
    if(power_on_rst_i) begin 
        power_on_state_flag <= 1'b0;    
    end 
    else if(power_on_rst_nege) begin 
        power_on_state_flag <= 1'b1; 
    end 
    else if(&csr_addr_end & !csr_addr_end_ff1) begin 
        power_on_state_flag <= 1'b0;
    end     
end 

always @ (posedge apb4_pclk_in or posedge apb4_preset_in) begin 
    if(apb4_preset_in) begin 
        csr_load_work <= 1'b0;
    end 
    else if(power_on_state_flag) begin 
        csr_load_work <= 1'b1;
    end 
    else if(csr_load_cnt >= CSR_LINENUM - 1) begin 
        if(slave_apb4_pready_in == 1'b1) begin 
            csr_load_work <= 1'b0;
        end 
    end 
end 

always @ (posedge apb4_pclk_in or posedge apb4_preset_in) begin 
    if(apb4_preset_in) begin 
        apb_delay_cnt <= 8'd0;
    end 
    else if(csr_load_work) begin 
        if(slave_apb4_pready_in == 1'b1) begin 
            apb_delay_cnt <= 8'd0;
        end
        else if (apb_delay_cnt >= DELAY_CNT) begin 
            apb_delay_cnt <= 8'd0;
        end         
        else begin 
            apb_delay_cnt <= apb_delay_cnt + 8'd1;
        end  
    end 
    else begin 
        apb_delay_cnt <= 8'd0;
    end 
end 

assign csr_addr_end = mem_csr_data[csr_load_cnt][63:32];

always @ (posedge apb4_pclk_in or posedge apb4_preset_in) begin  
    if(apb4_preset_in) begin 
        csr_addr_end_ff1 <= 1'b0;
    end 
    else begin 
        csr_addr_end_ff1 <= &csr_addr_end;
    end 
end 

//always @ (posedge apb4_pclk_in or posedge apb4_preset_in) begin 
//    if(apb4_preset_in) begin 
//        csr_load_cnt <= 9'd0;
//    end 
//    else if(csr_load_work) begin 
//        if(slave_apb4_pready_in == 1'b1 && (csr_load_cnt != CSR_LINENUM - 1)) begin
//            csr_load_cnt <= csr_load_cnt + 9'd1;
//        end  
//        else if(&csr_addr_end & !csr_addr_end_ff1) begin
//            if(hxt_ref1_en == 1'b0) begin  
//                csr_load_cnt <= CSR_LINENUM - 1;
//            end 
//            else begin 
//                csr_load_cnt <= CSR_LINENUM - 5;    //enable hxt refclk1 regs
//            end 
//        end 
//    end 
//    else begin 
//        csr_load_cnt <= 9'd0;
//    end 
//end 

always @ (posedge apb4_pclk_in) begin 
    if(csr_load_work) begin 
        if(slave_apb4_pready_in == 1'b1 && (csr_load_cnt != CSR_LINENUM - 1)) begin
            csr_load_cnt <= csr_load_cnt + 9'd1;
        end  
        else if(&csr_addr_end & !csr_addr_end_ff1) begin
            if(hxt_ref1_en == 1'b0) begin  
                csr_load_cnt <= CSR_LINENUM - 1;
            end 
            else begin 
                csr_load_cnt <= CSR_LINENUM - 5;    //enable hxt refclk1 regs
            end 
        end 
    end 
    else begin 
        csr_load_cnt <= 9'd0;
    end 
end 
///--------------------------------------------------------------------------------
always @ (posedge apb4_pclk_in or posedge power_on_rst_i) begin 
    if(power_on_rst_i == 1'b1) begin 
        csr_load_done_r <= 1'b0;
    end     
    else if(csr_load_cnt == CSR_LINENUM - 1 && (slave_apb4_pready_in == 1'b1)) begin
        csr_load_done_r <= 1'b1;
    end 
end 

always @ (posedge apb4_pclk_in or posedge power_on_rst_i) begin 
    if(power_on_rst_i == 1'b1) begin 
        csr_load_done <= 1'b0;
    end   
    else begin
        csr_load_done <= csr_load_done_r;
    end 
end

///--------------------------------------------------------------------------------

always @ (posedge apb4_pclk_in or posedge apb4_preset_in) begin 
    if(apb4_preset_in) begin 
        csr_load_work_ff1 <= 1'b0;
        csr_load_work_ff2 <= 1'b0;      
    end
    else begin 
        csr_load_work_ff1 <= csr_load_work;
        csr_load_work_ff2 <= csr_load_work_ff1;
    end 
end 

always @ (posedge apb4_pclk_in or posedge apb4_preset_in) begin 
    if(apb4_preset_in) begin 
        cmn_refclk_data <= 'd0;
    end     
    else if(apb_addr == 32'hdc && apb_write == 1'b0 && slave_apb4_pready_in == 1'b1) begin 
        cmn_refclk_data <= slave_apb4_prdata_in;
    end 
end 

always @ (posedge apb4_pclk_in or posedge apb4_preset_in) begin 
    if(apb4_preset_in) begin 
        pd_afe_cmn_data <= 'd0;
    end     
    else if(apb_addr == 32'h170 && apb_write == 1'b0 && slave_apb4_pready_in == 1'b1) begin 
        pd_afe_cmn_data <= slave_apb4_prdata_in;
    end 
end 

always @ (posedge apb4_pclk_in or posedge apb4_preset_in) begin 
    if(apb4_preset_in) begin 
        csr_addr <= 32'd0;
        csr_data <= 32'd0;
    end 
    else if(csr_load_work) begin 
        if(&csr_addr_end != 1'b1) begin
            if (csr_load_cnt == CSR_LINENUM - 1) begin
                csr_addr <=  32'h1a4    ;
                csr_data <=  32'h3      ;
            end
            else begin
                csr_addr <=  mem_csr_data[csr_load_cnt][63:32] ;
                csr_data <=  mem_csr_data[csr_load_cnt][31:0] ;
            end         
        end 
        else begin 
            case(csr_load_cnt)
                CSR_LINENUM - 5 : begin 
                    csr_addr <= 32'hdc;
                    csr_data <= 32'h0;                  
                end 
                CSR_LINENUM - 4 : begin 
                    csr_addr <= 32'hdc;
                    csr_data <= {cmn_refclk_data[31:12],hxt_ref1_float0_en,cmn_refclk_data[10:0]};                  
                end 
                CSR_LINENUM - 3 : begin 
                    csr_addr <= 32'h170;
                    csr_data <= 32'h0;                  
                end     
                CSR_LINENUM - 2 : begin 
                    csr_addr <= 32'h170;
                    csr_data <= {pd_afe_cmn_data[31:8],1'b1,pd_afe_cmn_data[6:0]};                  
                end                                              
                CSR_LINENUM - 1 : begin 
                    csr_addr <= 32'h1a4;
                    csr_data <= 32'h3;                  
                end 
                default : begin 
                    csr_addr <= mem_csr_data[csr_load_cnt][63:32];
                    csr_data <= mem_csr_data[csr_load_cnt][31:0];                 
                end 
            endcase             
        end 
    end 
end

always @ (posedge apb4_pclk_in or posedge apb4_preset_in) begin 
    if(apb4_preset_in) begin 
        apb_write       <= 1'b0;
        apb_sel         <= 1'b0;
        apb_wdata       <= 32'd0;
        apb_addr        <= 32'd0;
        apb_pstrobe     <= 4'd0;
        apb_enable_r    <= 1'b0;          
    end
    else if((csr_load_work & apb_delay_cnt == 8'd2)) begin
        apb_write       <= (csr_load_cnt == CSR_LINENUM - 5 || csr_load_cnt == CSR_LINENUM - 3) ? 1'b0 : 1'b1;
        apb_sel         <= 1'b1;   
        apb_addr        <= csr_addr;                
        apb_wdata       <= csr_data;  
        apb_pstrobe     <= (csr_load_cnt == CSR_LINENUM - 5 || csr_load_cnt == CSR_LINENUM - 3) ? 4'h0 : 4'hf; 
        apb_enable_r    <= 1'b1;   
    end  
    else if(slave_apb4_pready_in & csr_load_work) begin
        apb_write       <= apb_write;
        apb_sel         <= 1'b0; 
        apb_wdata       <= apb_wdata;
        apb_addr        <= apb_addr;        
        apb_pstrobe     <= 4'h0;  
        apb_enable_r    <= 1'b0;                      
            
        $display("apb write address: %h data: %h at time %t", csr_addr, csr_data, $time);           
    end 
end 

always @ (posedge apb4_pclk_in or posedge apb4_preset_in) begin 
    if(apb4_preset_in) begin       
        apb_enable      <= 1'b0;        
    end 
    else if(slave_apb4_pready_in) begin 
        apb_enable      <= 1'b0; 
    end 
    else begin 
        if(apb_delay_cnt < DELAY_CNT) begin
            apb_enable <= apb_enable_r;
        end 
        else begin 
            apb_enable <= 1'b0;
        end 
    end     
end 

///---------------------------------------------------------------------
/// tx fir
localparam  FIR_IDLE        = 4'd0;
localparam  FIR_TX0         = 4'd1;
localparam  FIR_TX0_STOP    = 4'd2;
localparam  FIR_TX1         = 4'd3;
localparam  FIR_TX1_STOP    = 4'd4;
localparam  FIR_TX2         = 4'd5;
localparam  FIR_TX2_STOP    = 4'd6;
localparam  FIR_TX3         = 4'd7;
localparam  FIR_TX3_STOP    = 4'd8;

localparam  FIR_TX0_REG     = {1'b1,5'd4,6'd50,5'd2,3'd0,3'd0}; //{en[22],c1_post[21:17],c0_main[16:11],c-1_pre[10:6],c-2_pre[5:3],c-3_pre[2:0]} 
localparam  FIR_TX1_REG     = {1'b1,5'd4,6'd50,5'd2,3'd0,3'd0}; //{en[22],c1_post[21:17],c0_main[16:11],c-1_pre[10:6],c-2_pre[5:3],c-3_pre[2:0]} 
localparam  FIR_TX2_REG     = {1'b1,5'd4,6'd50,5'd2,3'd0,3'd0}; //{en[22],c1_post[21:17],c0_main[16:11],c-1_pre[10:6],c-2_pre[5:3],c-3_pre[2:0]} 
localparam  FIR_TX3_REG     = {1'b1,5'd4,6'd50,5'd2,3'd0,3'd0}; //{en[22],c1_post[21:17],c0_main[16:11],c-1_pre[10:6],c-2_pre[5:3],c-3_pre[2:0]} 

reg     [3:0]   fir_cur_state       = 4'd0;//synthesis keep 
reg     [3:0]   fir_nxt_state             ;//synthesis keep 

reg     [3:0]   tx_fir_start_ff1    = 4'd0;
reg             tx0_fir_work        = 1'b0;
reg             tx1_fir_work        = 1'b0;
reg             tx2_fir_work        = 1'b0;
reg             tx3_fir_work        = 1'b0;

reg     [15:0]  fir_timeout_cnt     = 16'd0;//synthesis keep 

reg             fir_apb_write   = 1'b0      ;
reg             fir_apb_sel     = 1'b0      ;
reg     [31:0]  fir_apb_wdata   = 32'd0     ;//synthesis keep 
reg     [31:0]  fir_apb_addr    = 32'd0     ;//synthesis keep 
reg     [3:0]   fir_apb_pstrobe= 4'd0       ;
reg             fir_apb_enable = 1'b0       ;

reg     [31:0]  fir_apb_wdata_tmp   = 32'd0     ;
reg     [31:0]  fir_apb_addr_tmp    = 32'd0     ;

always @ (posedge apb4_pclk_in or posedge power_on_rst_i) begin 
    if(power_on_rst_i) begin 
        tx_fir_start_ff1 <= 4'd0;
    end 
    else begin 
        tx_fir_start_ff1 <= tx_fir_start_i;
    end 
end 

always @ (posedge apb4_pclk_in or posedge power_on_rst_i) begin 
    if(power_on_rst_i) begin 
        tx0_fir_work <= 1'b0;
    end 
    else if(!tx_fir_start_ff1[0] & tx_fir_start_i[0]) begin 
        tx0_fir_work <= 1'b1;
    end 
    else if(fir_cur_state == FIR_TX0_STOP) begin 
        tx0_fir_work <= 1'b0;
    end 
end 

always @ (posedge apb4_pclk_in or posedge power_on_rst_i) begin 
    if(power_on_rst_i) begin 
        tx1_fir_work <= 1'b0;
    end 
    else if(!tx_fir_start_ff1[1] & tx_fir_start_i[1]) begin 
        tx1_fir_work <= 1'b1;
    end 
    else if(fir_cur_state == FIR_TX1_STOP) begin 
        tx1_fir_work <= 1'b0;
    end 
end 

always @ (posedge apb4_pclk_in or posedge power_on_rst_i) begin 
    if(power_on_rst_i) begin 
        tx2_fir_work <= 1'b0;
    end 
    else if(!tx_fir_start_ff1[2] & tx_fir_start_i[2]) begin 
        tx2_fir_work <= 1'b1;
    end 
    else if(fir_cur_state == FIR_TX2_STOP) begin 
        tx2_fir_work <= 1'b0;
    end 
end 

always @ (posedge apb4_pclk_in or posedge power_on_rst_i) begin 
    if(power_on_rst_i) begin 
        tx3_fir_work <= 1'b0;
    end 
    else if(!tx_fir_start_ff1[3] & tx_fir_start_i[3]) begin 
        tx3_fir_work <= 1'b1;
    end 
    else if(fir_cur_state == FIR_TX3_STOP) begin 
        tx3_fir_work <= 1'b0;
    end 
end 

always @ (posedge apb4_pclk_in or posedge power_on_rst_i) begin 
    if(power_on_rst_i) begin 
        fir_timeout_cnt <= 'd0;
    end 
    else if(fir_cur_state == FIR_TX0 || fir_cur_state == FIR_TX1 || fir_cur_state == FIR_TX2 || fir_cur_state == FIR_TX3) begin 
        fir_timeout_cnt <= fir_timeout_cnt + 1'b1;
    end 
    else begin 
        fir_timeout_cnt <= 'd0;
    end 
end 

always @ (posedge apb4_pclk_in or posedge power_on_rst_i) begin 
    if(power_on_rst_i) begin 
        fir_cur_state <= FIR_IDLE;
    end 
    else begin 
        fir_cur_state <= fir_nxt_state;
    end 
end 

always @ ( * ) begin 
    case(fir_cur_state)
        FIR_IDLE : begin 
            if(tx0_fir_work == 1'b1) begin 
                fir_nxt_state = FIR_TX0;
            end 
            else if(tx1_fir_work == 1'b1) begin 
                fir_nxt_state = FIR_TX1;
            end 
            else if(tx2_fir_work == 1'b1) begin 
                fir_nxt_state = FIR_TX2;
            end   
            else if(tx3_fir_work == 1'b1) begin 
                fir_nxt_state = FIR_TX3;
            end 
            else begin 
                fir_nxt_state = FIR_IDLE;
            end          
        end 
        FIR_TX0 : begin 
            if(slave_apb4_pready_in == 1'b1) begin 
                fir_nxt_state = FIR_TX0_STOP;
            end
            else if(fir_timeout_cnt >= 500-1) begin 
                fir_nxt_state = FIR_TX0_STOP;
            end 
            else begin 
                fir_nxt_state = FIR_TX0;
            end  
        end 
        FIR_TX0_STOP : begin 
            fir_nxt_state = FIR_IDLE;
        end 
        
        FIR_TX1 : begin 
            if(slave_apb4_pready_in == 1'b1) begin 
                fir_nxt_state = FIR_TX1_STOP;
            end
            else if(fir_timeout_cnt >= 500-1) begin 
                fir_nxt_state = FIR_TX1_STOP;
            end 
            else begin 
                fir_nxt_state = FIR_TX1;
            end  
        end 
        FIR_TX1_STOP : begin 
            fir_nxt_state = FIR_IDLE;
        end 
        
        FIR_TX2 : begin 
            if(slave_apb4_pready_in == 1'b1) begin 
                fir_nxt_state = FIR_TX2_STOP;
            end
            else if(fir_timeout_cnt >= 500-1) begin 
                fir_nxt_state = FIR_TX2_STOP;
            end 
            else begin 
                fir_nxt_state = FIR_TX2;
            end  
        end 
        FIR_TX2_STOP : begin 
            fir_nxt_state = FIR_IDLE;
        end
        
        FIR_TX3 : begin 
            if(slave_apb4_pready_in == 1'b1) begin 
                fir_nxt_state = FIR_TX3_STOP;
            end
            else if(fir_timeout_cnt >= 500-1) begin 
                fir_nxt_state = FIR_TX3_STOP;
            end 
            else begin 
                fir_nxt_state = FIR_TX3;
            end  
        end 
        FIR_TX3_STOP : begin 
            fir_nxt_state = FIR_IDLE;
        end  
        default : fir_nxt_state = FIR_IDLE;                 
    endcase
end 

always @ (posedge apb4_pclk_in or posedge power_on_rst_i) begin 
    if(power_on_rst_i) begin  
        fir_apb_wdata_tmp       <= 32'd0;
        fir_apb_addr_tmp        <= 32'd0;         
    end
    else begin 
        case(fir_cur_state)
            FIR_TX0 : begin 
                fir_apb_addr_tmp    <= 32'h0200_1000 + 32'h0050; 
                if(loopback_en_i[0] == 1'b1 && ictl_loopback_mode_i[2:0] == 3'b001) begin 
                    fir_apb_wdata_tmp   <= {1'b1,5'd4,6'd25,5'd2,3'd0,3'd0}; //{c1_post,c0_main,c-1_pre,c-2_pre,c-3_pre} 
                end 
                else begin 
                    fir_apb_wdata_tmp   <= FIR_TX0_REG;     
                end                                 
            end 

            FIR_TX1 : begin 
                fir_apb_addr_tmp    <= 32'h0400_1000 + 32'h0050; 
                if(loopback_en_i[1] == 1'b1 && ictl_loopback_mode_i[5:3] == 3'b001) begin 
                    fir_apb_wdata_tmp   <= {1'b1,5'd4,6'd25,5'd2,3'd0,3'd0}; //{c1_post,c0_main,c-1_pre,c-2_pre,c-3_pre} 
                end 
                else begin 
                    fir_apb_wdata_tmp   <= FIR_TX1_REG;     
                end                                 
            end     
            
            FIR_TX2 : begin 
                fir_apb_addr_tmp    <= 32'h0600_1000 + 32'h0050; 
                if(loopback_en_i[2] == 1'b1 && ictl_loopback_mode_i[8:6] == 3'b001) begin 
                    fir_apb_wdata_tmp   <= {1'b1,5'd4,6'd25,5'd2,3'd0,3'd0}; //{c1_post,c0_main,c-1_pre,c-2_pre,c-3_pre} 
                end 
                else begin 
                    fir_apb_wdata_tmp   <= FIR_TX2_REG;     
                end                                 
            end  
            
            FIR_TX3 : begin 
                fir_apb_addr_tmp    <= 32'h0800_1000 + 32'h0050; 
                if(loopback_en_i[3] == 1'b1 && ictl_loopback_mode_i[11:9] == 3'b001) begin 
                    fir_apb_wdata_tmp   <= {1'b1,5'd4,6'd25,5'd2,3'd0,3'd0}; //{c1_post,c0_main,c-1_pre,c-2_pre,c-3_pre} 
                end 
                else begin 
                    fir_apb_wdata_tmp   <= FIR_TX3_REG;     
                end                                 
            end 
                                           
            default : ;                               
        endcase       
    end 
end

always @ (posedge apb4_pclk_in or posedge power_on_rst_i) begin 
    if(power_on_rst_i) begin  
        fir_apb_write       <= 1'b0;
        fir_apb_sel         <= 1'b0;
        fir_apb_wdata       <= 32'd0;
        fir_apb_addr        <= 32'd0;
        fir_apb_pstrobe     <= 4'd0;         
    end
    else if(fir_timeout_cnt == 3) begin 
        fir_apb_write   <= 1'b1;
        fir_apb_sel         <= 1'b1;
        fir_apb_addr        <= fir_apb_addr_tmp;                
        fir_apb_wdata       <= fir_apb_wdata_tmp;  
        fir_apb_pstrobe     <= 4'hf; 
    end 
    else if(slave_apb4_pready_in) begin 
        fir_apb_write       <= fir_apb_write;
        fir_apb_sel         <= 1'b0; 
        fir_apb_addr        <= fir_apb_addr;
        fir_apb_wdata       <= fir_apb_wdata;        
        fir_apb_pstrobe     <= 4'h0;                     
            
        if(tx0_fir_work | tx1_fir_work | tx2_fir_work | tx3_fir_work) begin 
            $display("apb write address: %h data: %h at time %t", fir_apb_addr_tmp, fir_apb_wdata_tmp, $time);     
        end 
    end
end     
    
always @ (posedge apb4_pclk_in or posedge power_on_rst_i) begin 
    if(power_on_rst_i) begin  
        fir_apb_enable      <= 1'b0;          
    end
    else if(fir_timeout_cnt == 4) begin 
        fir_apb_enable      <= 1'b1;
    end 
    else if(slave_apb4_pready_in) begin 
        fir_apb_enable      <= 1'b0;                         
    end
end 

///---------------------------------------------------------------------                                                                
/// elbk
localparam  EQBK_IDLE        = 5'd0;
localparam  EQBK_RX0         = 5'd1;
localparam  EQBK_RX0_STOP    = 5'd2;
localparam  EQBK_RX1         = 5'd3;
localparam  EQBK_RX1_STOP    = 5'd4;
localparam  EQBK_RX2         = 5'd5;
localparam  EQBK_RX2_STOP    = 5'd6;
localparam  EQBK_RX3         = 5'd7;
localparam  EQBK_RX3_STOP    = 5'd8;
localparam  EQBK_RX0_DONE    = 5'd9;
localparam  EQBK_RX1_DONE    = 5'd10;
localparam  EQBK_RX2_DONE    = 5'd11;
localparam  EQBK_RX3_DONE    = 5'd12;
localparam  EQBK_RX0_DONE1   = 5'd13;
localparam  EQBK_RX1_DONE1   = 5'd14;
localparam  EQBK_RX2_DONE1   = 5'd15;
localparam  EQBK_RX3_DONE1   = 5'd16;

//localparam  EQBK_LINKEVAL_TIMEOUT = 32'd50_000_000/10; //100ms
//localparam  EQBK_START_DELAY_CNT = SIMULATION_EN ? 32'd50_000_000/1000_000 : 32'd50_000_000/25; //40ms
localparam  EQBK_START_DELAY_CNT =  50 ; //0.4ms

reg     [4:0]   cur_state   = 5'd0;//synthesis keep 
reg     [4:0]   nxt_state         ;//synthesis keep 

reg     [3:0]   rx_eqbk_start_tmp       = 4'd0;
reg     [3:0]   rx_eqbk_start_tmp_ff1   = 4'd0;
reg     [3:0]   rx_eqbk_start_tmp_ff2   = 4'd0;
reg     [3:0]   rx_eqbk_start_tmp_work  = 4'd0;

reg     [3:0]   rx_eqbk_start_ff1   = 4'd0;
reg     [3:0]   rx_eqbk_start_ff2   = 4'd0;
reg     [3:0]   rx_linkeval_ack_ff1 = 4'd0;
reg     [3:0]   rx_linkeval_ack_ff2 = 4'd0;
reg             rx0_eqbk_work       = 1'b0; 
reg             rx1_eqbk_work       = 1'b0;
reg             rx2_eqbk_work       = 1'b0;
reg             rx3_eqbk_work       = 1'b0;
reg     [2:0]   eqbk_rx_cnt         = 3'd0;//synthesis keep 

reg             rx0_eqbk_start_pose = 1'b0;
reg             rx1_eqbk_start_pose = 1'b0;
reg             rx2_eqbk_start_pose = 1'b0;
reg             rx3_eqbk_start_pose = 1'b0;

reg             rx0_linkeval_ack_pose = 1'b0;
reg             rx1_linkeval_ack_pose = 1'b0;
reg             rx2_linkeval_ack_pose = 1'b0;
reg             rx3_linkeval_ack_pose = 1'b0;

reg [15:0]      eqbk_timeout_cnt            = 16'd0;//synthesis keep    
reg [31:0]      eqbk_apb_wdata_tmp          = 32'd0;//synthesis keep 
reg [31:0]      eqbk_apb_addr_tmp           = 32'd0;//synthesis keep 
reg [31:0]      eqbk_linkeval_timeout_cnt   = 32'd0;

reg             eqbk_apb_mask   = 1'b0      ;//synthesis keep   
reg             eqbk_apb_write  = 1'b0      ;
reg             eqbk_apb_sel    = 1'b0      ;
reg     [31:0]  eqbk_apb_wdata  = 32'd0     ;//synthesis keep 
reg     [31:0]  eqbk_apb_addr   = 32'd0     ;//synthesis keep 
reg     [3:0]   eqbk_apb_pstrobe= 4'd0      ;
reg             eqbk_apb_enable = 1'b0      ;

reg [31:0]      eqbk_rx0_start_delay    = 32'd0;
reg [31:0]      eqbk_rx1_start_delay    = 32'd0;
reg [31:0]      eqbk_rx2_start_delay    = 32'd0;
reg [31:0]      eqbk_rx3_start_delay    = 32'd0;            

reg [3:0]       eqbk_linkeval_ack_hold  = 4'b0000;

reg             rx0_eqbk_work_ff1           ;
reg             rx1_eqbk_work_ff1           ;
reg             rx2_eqbk_work_ff1           ;
reg             rx3_eqbk_work_ff1           ;

always @ (posedge apb4_pclk_in or posedge power_on_rst_i) begin 
    if(power_on_rst_i) begin 
        rx_eqbk_start_tmp       <= 'd0;
        rx_eqbk_start_tmp_ff1   <= 'd0;
        rx_eqbk_start_tmp_ff2   <= 'd0;
    end
    else begin 
        rx_eqbk_start_tmp       <= rx_eqbk_start_i;
        rx_eqbk_start_tmp_ff1   <= rx_eqbk_start_tmp;
        rx_eqbk_start_tmp_ff2   <= rx_eqbk_start_tmp_ff1;       
    end  
end 

always @ (posedge apb4_pclk_in or posedge power_on_rst_i) begin 
    if(power_on_rst_i) begin 
        rx_eqbk_start_tmp_work[0]       <= 1'b0;
    end
    else if(!rx_eqbk_start_tmp_ff2[0] & rx_eqbk_start_tmp_ff1[0]) begin 
        rx_eqbk_start_tmp_work[0]       <= 1'b1;
    end
    else if(cur_state == EQBK_RX0_STOP) begin 
        rx_eqbk_start_tmp_work[0]       <= 1'b0;
    end  
end 

always @ (posedge apb4_pclk_in or posedge power_on_rst_i) begin 
    if(power_on_rst_i) begin 
        rx_eqbk_start_tmp_work[1]       <= 1'b0;
    end
    else if(!rx_eqbk_start_tmp_ff2[1] & rx_eqbk_start_tmp_ff1[1]) begin 
        rx_eqbk_start_tmp_work[1]       <= 1'b1;
    end
    else if(cur_state == EQBK_RX1_STOP) begin 
        rx_eqbk_start_tmp_work[1]       <= 1'b0;
    end  
end

always @ (posedge apb4_pclk_in or posedge power_on_rst_i) begin 
    if(power_on_rst_i) begin 
        rx_eqbk_start_tmp_work[2]       <= 1'b0;
    end
    else if(!rx_eqbk_start_tmp_ff2[2] & rx_eqbk_start_tmp_ff1[2]) begin 
        rx_eqbk_start_tmp_work[2]       <= 1'b1;
    end
    else if(cur_state == EQBK_RX2_STOP) begin 
        rx_eqbk_start_tmp_work[2]       <= 1'b0;
    end  
end

always @ (posedge apb4_pclk_in or posedge power_on_rst_i) begin 
    if(power_on_rst_i) begin 
        rx_eqbk_start_tmp_work[3]       <= 1'b0;
    end
    else if(!rx_eqbk_start_tmp_ff2[3] & rx_eqbk_start_tmp_ff1[3]) begin 
        rx_eqbk_start_tmp_work[3]       <= 1'b1;
    end
    else if(cur_state == EQBK_RX3_STOP) begin 
        rx_eqbk_start_tmp_work[3]       <= 1'b0;
    end  
end

always @ (posedge apb4_pclk_in or posedge power_on_rst_i) begin 
    if(power_on_rst_i) begin 
        eqbk_rx0_start_delay    <= 32'd0;
        rx_eqbk_start_ff1[0]    <= 1'b0;
    end 
    else if(rx_eqbk_start_tmp_work[0] == 1'b0) begin 
        eqbk_rx0_start_delay    <= 32'd0;
        rx_eqbk_start_ff1[0]    <= 1'b0;        
    end 
    else if(eqbk_rx0_start_delay <= EQBK_START_DELAY_CNT - 1) begin 
        eqbk_rx0_start_delay    <= eqbk_rx0_start_delay + 32'd1;
        rx_eqbk_start_ff1[0]    <= 1'b0;
    end 
    else begin 
        eqbk_rx0_start_delay    <= eqbk_rx0_start_delay;
        rx_eqbk_start_ff1[0]    <= 1'b1;    
    end 
end

always @ (posedge apb4_pclk_in or posedge power_on_rst_i) begin 
    if(power_on_rst_i) begin 
        eqbk_rx1_start_delay    <= 32'd0;
        rx_eqbk_start_ff1[1]    <= 1'b0;
    end 
    else if(rx_eqbk_start_tmp_work[1] == 1'b0) begin 
        eqbk_rx1_start_delay    <= 32'd0;
        rx_eqbk_start_ff1[1]    <= 1'b0;        
    end 
    else if(eqbk_rx1_start_delay <= EQBK_START_DELAY_CNT - 1) begin 
        eqbk_rx1_start_delay    <= eqbk_rx1_start_delay + 32'd1;
        rx_eqbk_start_ff1[1]    <= 1'b0;
    end 
    else begin 
        eqbk_rx1_start_delay    <= eqbk_rx1_start_delay;
        rx_eqbk_start_ff1[1]    <= 1'b1;    
    end 
end

always @ (posedge apb4_pclk_in or posedge power_on_rst_i) begin 
    if(power_on_rst_i) begin 
        eqbk_rx2_start_delay    <= 32'd0;
        rx_eqbk_start_ff1[2]    <= 1'b0;
    end 
    else if(rx_eqbk_start_tmp_work[2] == 1'b0) begin 
        eqbk_rx2_start_delay    <= 32'd0;
        rx_eqbk_start_ff1[2]    <= 1'b0;        
    end 
    else if(eqbk_rx2_start_delay <= EQBK_START_DELAY_CNT - 1) begin 
        eqbk_rx2_start_delay    <= eqbk_rx2_start_delay + 32'd1;
        rx_eqbk_start_ff1[2]    <= 1'b0;
    end 
    else begin 
        eqbk_rx2_start_delay    <= eqbk_rx2_start_delay;
        rx_eqbk_start_ff1[2]    <= 1'b1;    
    end 
end

always @ (posedge apb4_pclk_in or posedge power_on_rst_i) begin 
    if(power_on_rst_i) begin 
        eqbk_rx3_start_delay    <= 32'd0;
        rx_eqbk_start_ff1[3]    <= 1'b0;
    end 
    else if(rx_eqbk_start_tmp_work[3] == 1'b0) begin 
        eqbk_rx3_start_delay    <= 32'd0;
        rx_eqbk_start_ff1[3]    <= 1'b0;        
    end 
    else if(eqbk_rx3_start_delay <= EQBK_START_DELAY_CNT - 1) begin 
        eqbk_rx3_start_delay    <= eqbk_rx3_start_delay + 32'd1;
        rx_eqbk_start_ff1[3]    <= 1'b0;
    end 
    else begin 
        eqbk_rx3_start_delay    <= eqbk_rx3_start_delay;
        rx_eqbk_start_ff1[3]    <= 1'b1;    
    end 
end

always @ (posedge apb4_pclk_in or posedge power_on_rst_i) begin 
    if(power_on_rst_i) begin       
        rx_linkeval_ack_ff1 <= 'd0;  
        rx_linkeval_ack_ff2 <= 'd0;
        rx_eqbk_start_ff2   <= 'd0;    
        rx0_eqbk_start_pose <= 1'b0;
        rx1_eqbk_start_pose <= 1'b0;
        rx2_eqbk_start_pose <= 1'b0;
        rx3_eqbk_start_pose <= 1'b0;
        
        rx0_linkeval_ack_pose <= 1'b0;
        rx1_linkeval_ack_pose <= 1'b0;
        rx2_linkeval_ack_pose <= 1'b0;        
        rx3_linkeval_ack_pose <= 1'b0;                      
    end
    else begin 
        rx_linkeval_ack_ff1 <= rx_linkeval_ack_i;
        rx_linkeval_ack_ff2 <= rx_linkeval_ack_ff1;
        rx_eqbk_start_ff2   <= rx_eqbk_start_ff1;
        rx0_eqbk_start_pose <= !rx_eqbk_start_ff2[0] & rx_eqbk_start_ff1[0];
        rx1_eqbk_start_pose <= !rx_eqbk_start_ff2[1] & rx_eqbk_start_ff1[1];
        rx2_eqbk_start_pose <= !rx_eqbk_start_ff2[2] & rx_eqbk_start_ff1[2];
        rx3_eqbk_start_pose <= !rx_eqbk_start_ff2[3] & rx_eqbk_start_ff1[3];        
        
        rx0_linkeval_ack_pose <= !rx_linkeval_ack_ff2[0] & rx_linkeval_ack_ff1[0];
        rx1_linkeval_ack_pose <= !rx_linkeval_ack_ff2[1] & rx_linkeval_ack_ff1[1];
        rx2_linkeval_ack_pose <= !rx_linkeval_ack_ff2[2] & rx_linkeval_ack_ff1[2];
        rx3_linkeval_ack_pose <= !rx_linkeval_ack_ff2[3] & rx_linkeval_ack_ff1[3]; 
                    
    end     
end 

always @ (posedge apb4_pclk_in or posedge power_on_rst_i) begin 
    if(power_on_rst_i) begin 
        cur_state <= EQBK_IDLE;
    end 
    else begin 
        cur_state <= nxt_state;
    end 
end 

always @ ( * ) begin 
    case(cur_state)
        EQBK_IDLE : begin 
            if(rx0_eqbk_work) begin 
                nxt_state = EQBK_RX0;
            end 
            else if(rx1_eqbk_work) begin 
                nxt_state = EQBK_RX1;
            end 
            else if(rx2_eqbk_work) begin 
                nxt_state = EQBK_RX2;   
            end 
            else if(rx3_eqbk_work) begin 
                nxt_state = EQBK_RX3;   
            end 

            else if(eqbk_linkeval_ack_hold[0]) begin
                nxt_state = EQBK_RX0_DONE;   
            end 
            else if(eqbk_linkeval_ack_hold[1]) begin 
                nxt_state = EQBK_RX1_DONE;   
            end   
            else if(eqbk_linkeval_ack_hold[2]) begin 
                nxt_state = EQBK_RX2_DONE;   
            end   
            else if(eqbk_linkeval_ack_hold[3]) begin 
                nxt_state = EQBK_RX3_DONE;   
            end               

            else begin 
                nxt_state = EQBK_IDLE;
            end 
        end
        
        EQBK_RX0 : begin  
            if(eqbk_rx_cnt >= 3'd2) begin
                if(slave_apb4_pready_in) begin                           
                    nxt_state = EQBK_RX0_STOP;
                end
                else if(eqbk_timeout_cnt >= 500) begin 
                    nxt_state = EQBK_RX0_STOP;
                end 
                else begin 
                    nxt_state = EQBK_RX0;
                end                     
            end  
            else begin 
                nxt_state = EQBK_RX0;
            end 
        end 

        EQBK_RX0_DONE : begin 
            if(slave_apb4_pready_in) begin 
                nxt_state = EQBK_RX0_DONE1; 
            end 
            else if(eqbk_timeout_cnt >= 500) begin 
                nxt_state = EQBK_RX0_DONE1;
            end            
            else begin 
                nxt_state = EQBK_RX0_DONE; 
            end       
        end 

        EQBK_RX0_DONE1 : begin 
            if(slave_apb4_pready_in) begin 
                nxt_state = EQBK_IDLE; 
            end 
            else if(eqbk_timeout_cnt >= 500) begin 
                nxt_state = EQBK_IDLE;
            end            
            else begin 
                nxt_state = EQBK_RX0_DONE1; 
            end       
        end          
        
        EQBK_RX0_STOP : begin 
            nxt_state = EQBK_IDLE;
        end 
         
        EQBK_RX1 : begin  
            if(eqbk_rx_cnt >= 3'd2) begin
                if(slave_apb4_pready_in) begin                           
                    nxt_state = EQBK_RX1_STOP;
                end
                else if(eqbk_timeout_cnt >= 500) begin 
                    nxt_state = EQBK_RX1_STOP;
                end 
                else begin 
                    nxt_state = EQBK_RX1;
                end                     
            end  
            else begin 
                nxt_state = EQBK_RX1;
            end 
        end 

        EQBK_RX1_DONE : begin 
            if(slave_apb4_pready_in) begin 
                nxt_state = EQBK_RX1_DONE1; 
            end 
            else if(eqbk_timeout_cnt >= 500) begin 
                nxt_state = EQBK_RX1_DONE1;
            end                
            else begin 
                nxt_state = EQBK_RX1_DONE; 
            end       
        end 

        EQBK_RX1_DONE1 : begin 
            if(slave_apb4_pready_in) begin 
                nxt_state = EQBK_IDLE; 
            end 
            else if(eqbk_timeout_cnt >= 500) begin 
                nxt_state = EQBK_IDLE;
            end            
            else begin 
                nxt_state = EQBK_RX1_DONE1; 
            end       
        end           
        
        EQBK_RX1_STOP : begin 
            nxt_state = EQBK_IDLE;
        end        
        
        EQBK_RX2 : begin  
            if(eqbk_rx_cnt >= 3'd2) begin
                if(slave_apb4_pready_in) begin                           
                    nxt_state = EQBK_RX2_STOP;
                end
                else if(eqbk_timeout_cnt >= 500) begin 
                    nxt_state = EQBK_RX2_STOP;
                end 
                else begin 
                    nxt_state = EQBK_RX2;
                end                     
            end  
            else begin 
                nxt_state = EQBK_RX2;
            end 
        end 

        EQBK_RX2_DONE : begin 
            if(slave_apb4_pready_in) begin 
                nxt_state = EQBK_RX2_DONE1; 
            end 
            else if(eqbk_timeout_cnt >= 500) begin 
                nxt_state = EQBK_RX2_DONE1;
            end                
            else begin 
                nxt_state = EQBK_RX2_DONE; 
            end       
        end 

        EQBK_RX2_DONE1 : begin 
            if(slave_apb4_pready_in) begin 
                nxt_state = EQBK_IDLE; 
            end 
            else if(eqbk_timeout_cnt >= 500) begin 
                nxt_state = EQBK_IDLE;
            end            
            else begin 
                nxt_state = EQBK_RX2_DONE1; 
            end       
        end          
        
        EQBK_RX2_STOP : begin 
            nxt_state = EQBK_IDLE;
        end 
        
        EQBK_RX3 : begin  

            if(eqbk_rx_cnt >= 3'd2) begin
                if(slave_apb4_pready_in) begin                           
                    nxt_state = EQBK_RX3_STOP;
                end
                else if(eqbk_timeout_cnt >= 500) begin 
                    nxt_state = EQBK_RX3_STOP;
                end 
                else begin 
                    nxt_state = EQBK_RX3;
                end                     
            end  
            else begin 
                nxt_state = EQBK_RX3;
            end 
        end 

        EQBK_RX3_DONE : begin 
            if(slave_apb4_pready_in) begin 
                nxt_state = EQBK_RX3_DONE1; 
            end
            else if(eqbk_timeout_cnt >= 500) begin 
                nxt_state = EQBK_RX3_DONE1;
            end                 
            else begin 
                nxt_state = EQBK_RX3_DONE; 
            end       
        end 

        EQBK_RX3_DONE1 : begin 
            if(slave_apb4_pready_in) begin 
                nxt_state = EQBK_IDLE; 
            end 
            else if(eqbk_timeout_cnt >= 500) begin 
                nxt_state = EQBK_IDLE;
            end            
            else begin 
                nxt_state = EQBK_RX3_DONE1; 
            end       
        end          
        EQBK_RX3_STOP : begin 
            nxt_state = EQBK_IDLE;
        end 
                            
        default : begin 
            nxt_state = EQBK_IDLE;
        end 
    endcase
end 

always @ (posedge apb4_pclk_in or posedge power_on_rst_i) begin 
    if(power_on_rst_i) begin 
        eqbk_linkeval_ack_hold[0] <= 1'b0;
    end 
    else if(rx0_linkeval_ack_pose) begin 
        eqbk_linkeval_ack_hold[0] <= 1'b1;
    end
    else if(cur_state == EQBK_RX0_DONE && slave_apb4_pready_in) begin 
        eqbk_linkeval_ack_hold[0] <= 1'b0;
    end     
end 

always @ (posedge apb4_pclk_in or posedge power_on_rst_i) begin 
    if(power_on_rst_i) begin 
        eqbk_linkeval_ack_hold[1] <= 1'b0;
    end 
    else if(rx1_linkeval_ack_pose) begin 
        eqbk_linkeval_ack_hold[1] <= 1'b1;
    end
    else if(cur_state == EQBK_RX1_DONE && slave_apb4_pready_in) begin 
        eqbk_linkeval_ack_hold[1] <= 1'b0;
    end     
end 

always @ (posedge apb4_pclk_in or posedge power_on_rst_i) begin 
    if(power_on_rst_i) begin 
        eqbk_linkeval_ack_hold[2] <= 1'b0;
    end 
    else if(rx2_linkeval_ack_pose) begin 
        eqbk_linkeval_ack_hold[2] <= 1'b1;
    end
    else if(cur_state == EQBK_RX2_DONE && slave_apb4_pready_in) begin 
        eqbk_linkeval_ack_hold[2] <= 1'b0;
    end     
end 

always @ (posedge apb4_pclk_in or posedge power_on_rst_i) begin 
    if(power_on_rst_i) begin 
        eqbk_linkeval_ack_hold[3] <= 1'b0;
    end 
    else if(rx3_linkeval_ack_pose) begin 
        eqbk_linkeval_ack_hold[3] <= 1'b1;
    end
    else if(cur_state == EQBK_RX3_DONE && slave_apb4_pready_in) begin 
        eqbk_linkeval_ack_hold[3] <= 1'b0;
    end     
end 

always @ (posedge apb4_pclk_in or posedge power_on_rst_i) begin 
    if(power_on_rst_i) begin       
        rx0_eqbk_work <= 'd0; 
    end
    else begin 
        if(rx0_eqbk_start_pose) begin 
            rx0_eqbk_work <= 1'b1;
        end
        else if(cur_state == EQBK_RX0_STOP) begin 
            rx0_eqbk_work <= 1'b0;
        end                             
    end
end 

always @ (posedge apb4_pclk_in or posedge power_on_rst_i) begin 
    if(power_on_rst_i) begin       
        rx1_eqbk_work <= 'd0; 
    end
    else begin 
        if(rx1_eqbk_start_pose) begin 
            rx1_eqbk_work <= 1'b1;
        end
        else if(cur_state == EQBK_RX1_STOP) begin 
            rx1_eqbk_work <= 1'b0;
        end                             
    end
end 

always @ (posedge apb4_pclk_in or posedge power_on_rst_i) begin 
    if(power_on_rst_i) begin       
        rx2_eqbk_work <= 'd0; 
    end
    else begin 
        if(rx2_eqbk_start_pose) begin 
            rx2_eqbk_work <= 1'b1;
        end
        else if(cur_state == EQBK_RX2_STOP) begin 
            rx2_eqbk_work <= 1'b0;
        end                             
    end
end 

always @ (posedge apb4_pclk_in or posedge power_on_rst_i) begin 
    if(power_on_rst_i) begin       
        rx3_eqbk_work <= 'd0; 
    end
    else begin 
        if(rx3_eqbk_start_pose) begin 
            rx3_eqbk_work <= 1'b1;
        end
        else if(cur_state == EQBK_RX3_STOP) begin 
            rx3_eqbk_work <= 1'b0;
        end                             
    end
end 

always @ (posedge apb4_pclk_in or posedge power_on_rst_i) begin 
    if(power_on_rst_i) begin      
        eqbk_timeout_cnt <= 'd0;
    end 
    else if(cur_state != EQBK_IDLE) begin 
        if(slave_apb4_pready_in | eqbk_apb_mask) begin 
            eqbk_timeout_cnt <= 'd0;    
        end
        else begin 
            eqbk_timeout_cnt <= eqbk_timeout_cnt + 1'b1;
        end 
    end 
    else begin 
        eqbk_timeout_cnt <= 'd0;
    end   
end 
         
always @ (posedge apb4_pclk_in or posedge power_on_rst_i) begin 
    if(power_on_rst_i) begin  
        eqbk_linkeval_timeout_cnt <= 'd0;
    end 
    else if(eqbk_apb_mask == 1'b1) begin
        eqbk_linkeval_timeout_cnt <= eqbk_linkeval_timeout_cnt + 1'b1;
    end  
    else begin 
        eqbk_linkeval_timeout_cnt <= 'd0;       
    end     
end 

always @ (posedge apb4_pclk_in or posedge power_on_rst_i) begin 
    if(power_on_rst_i) begin      
        eqbk_rx_cnt <= 'd0;
    end 
    else if(cur_state == EQBK_RX0 || cur_state == EQBK_RX1 || cur_state == EQBK_RX2 || cur_state == EQBK_RX3) begin 
        if(eqbk_rx_cnt < 3'd2) begin 
            if(slave_apb4_pready_in) begin 
                eqbk_rx_cnt <= eqbk_rx_cnt + 1'b1;
            end 
            else if(eqbk_timeout_cnt >= 500) begin 
                eqbk_rx_cnt <= eqbk_rx_cnt + 1'b1;
            end             
        end
    end    
    else begin 
        eqbk_rx_cnt <= 'd0; 
    end 
end 

always @ (posedge apb4_pclk_in or posedge power_on_rst_i) begin 
    if(power_on_rst_i) begin  
        eqbk_apb_mask <= 1'b0;
    end 
    else if(eqbk_rx_cnt == 3'd2) begin
        if(slave_apb4_pready_in) begin 
            eqbk_apb_mask <= 1'b1;
        end  
    end 
    else begin 
        eqbk_apb_mask <= 1'b0;      
    end 
end 

assign rx_linkeval_start_o[0] = (cur_state == EQBK_RX0) && (eqbk_rx_cnt == 3'd2) && slave_apb4_pready_in;
assign rx_linkeval_start_o[1] = (cur_state == EQBK_RX1) && (eqbk_rx_cnt == 3'd2) && slave_apb4_pready_in;
assign rx_linkeval_start_o[2] = (cur_state == EQBK_RX2) && (eqbk_rx_cnt == 3'd2) && slave_apb4_pready_in;
assign rx_linkeval_start_o[3] = (cur_state == EQBK_RX3) && (eqbk_rx_cnt == 3'd2) && slave_apb4_pready_in;

always @ (posedge apb4_pclk_in or posedge power_on_rst_i) begin 
    if(power_on_rst_i) begin  
        eqbk_apb_wdata_tmp      <= 32'd0;
        eqbk_apb_addr_tmp       <= 32'd0;         
    end
    else begin 
        case(cur_state)
            EQBK_RX0 : begin 
                case(eqbk_rx_cnt)
                    // 3'd0 : begin 
                    //     eqbk_apb_addr_tmp   <= 32'h0200_0000 + 32'h0914;                   
                    //     eqbk_apb_wdata_tmp  <= 32'h8000_0000;  
                    // end  
                    // 3'd1 : begin 
                    //     eqbk_apb_addr_tmp   <= 32'h0200_0000 + 32'h0914;                   
                    //     eqbk_apb_wdata_tmp  <= 32'h9000_0000;  
                    // end                    
                    // 3'd2 : begin 
                    //     eqbk_apb_addr_tmp   <= 32'h0200_0000 + 32'h0898;                   
                    //     eqbk_apb_wdata_tmp  <= 32'h0000_0010;  
                    // end

                    3'd0 : begin 
                        eqbk_apb_addr_tmp   <= 32'h0200_0000 + 32'h0914;                   
                        eqbk_apb_wdata_tmp  <= 32'h9000_0000;   
                    end  
                    3'd1 : begin 
                        eqbk_apb_addr_tmp   <= 32'h0200_0000 + 32'h0898;                   
                        eqbk_apb_wdata_tmp  <= 32'h0000_0010;  
                    end                    
                    3'd2 : begin 
                        eqbk_apb_addr_tmp   <= 32'h0200_0000 + 32'h0860;                   
                        eqbk_apb_wdata_tmp  <= 32'h0000_0003;  
                    end                    
                    default : ;                                                                 
                endcase          
            end 

            EQBK_RX0_DONE : begin  
                eqbk_apb_addr_tmp   <= 32'h0200_0000 + 32'h0860;                   
                eqbk_apb_wdata_tmp  <= 32'h0000_0001;                  
            end 

            EQBK_RX0_DONE1 : begin 
                eqbk_apb_addr_tmp   <= 32'h0200_0000 + 32'h0914;                   
                eqbk_apb_wdata_tmp  <= 32'h1000_0000;                  
            end             
            
            EQBK_RX1 : begin 
                case(eqbk_rx_cnt)
                    3'd0 : begin 
                        eqbk_apb_addr_tmp   <= 32'h0400_0000 + 32'h0914;                   
                        eqbk_apb_wdata_tmp  <= 32'h9000_0000;   
                    end  
                    3'd1 : begin 
                        eqbk_apb_addr_tmp   <= 32'h0400_0000 + 32'h0898;                   
                        eqbk_apb_wdata_tmp  <= 32'h0000_0010;  
                    end                    
                    3'd2 : begin 
                        eqbk_apb_addr_tmp   <= 32'h0400_0000 + 32'h0860;                   
                        eqbk_apb_wdata_tmp  <= 32'h0000_0003;  
                    end 
                    default :;                                                                                     
                endcase          
            end   

            EQBK_RX1_DONE : begin 
                eqbk_apb_addr_tmp   <= 32'h0400_0000 + 32'h0860;                   
                eqbk_apb_wdata_tmp  <= 32'h0000_0001;  
            end 

            EQBK_RX1_DONE1 : begin 
                eqbk_apb_addr_tmp   <= 32'h0400_0000 + 32'h0914;                   
                eqbk_apb_wdata_tmp  <= 32'h1000_0000;                  
            end               

            EQBK_RX2 : begin 
                case(eqbk_rx_cnt)                
                    3'd0 : begin 
                        eqbk_apb_addr_tmp   <= 32'h0600_0000 + 32'h0914;                   
                        eqbk_apb_wdata_tmp  <= 32'h9000_0000;   
                    end  
                    3'd1 : begin 
                        eqbk_apb_addr_tmp   <= 32'h0600_0000 + 32'h0898;                   
                        eqbk_apb_wdata_tmp  <= 32'h0000_0010;  
                    end                    
                    3'd2 : begin 
                        eqbk_apb_addr_tmp   <= 32'h0600_0000 + 32'h0860;                   
                        eqbk_apb_wdata_tmp  <= 32'h0000_0003;  
                    end
                    default :;                                                                                     
                endcase          
            end  

            EQBK_RX2_DONE : begin 
                eqbk_apb_addr_tmp   <= 32'h0600_0000 + 32'h0860;                   
                eqbk_apb_wdata_tmp  <= 32'h0000_0001;  
            end             
            
            EQBK_RX2_DONE1 : begin 
                eqbk_apb_addr_tmp   <= 32'h0600_0000 + 32'h0914;                   
                eqbk_apb_wdata_tmp  <= 32'h1000_0000;                  
            end 

            EQBK_RX3 : begin 
                case(eqbk_rx_cnt)
                    3'd0 : begin 
                        eqbk_apb_addr_tmp   <= 32'h0800_0000 + 32'h0914;                   
                        eqbk_apb_wdata_tmp  <= 32'h9000_0000;   
                    end  
                    3'd1 : begin 
                        eqbk_apb_addr_tmp   <= 32'h0800_0000 + 32'h0898;                   
                        eqbk_apb_wdata_tmp  <= 32'h0000_0010;  
                    end                    
                    3'd2 : begin 
                        eqbk_apb_addr_tmp   <= 32'h0800_0000 + 32'h0860;                   
                        eqbk_apb_wdata_tmp  <= 32'h0000_0003;  
                    end
                    default :;                                                                                     
                endcase          
            end 

            EQBK_RX3_DONE : begin 
                eqbk_apb_addr_tmp   <= 32'h0800_0000 + 32'h0860;                   
                eqbk_apb_wdata_tmp  <= 32'h0000_0001;    
            end 

            EQBK_RX3_DONE1 : begin 
                eqbk_apb_addr_tmp   <= 32'h0800_0000 + 32'h0914;                   
                eqbk_apb_wdata_tmp  <= 32'h1000_0000;                  
            end 
            default : ;                               
        endcase       
    end 
end

always @ (posedge apb4_pclk_in or posedge power_on_rst_i) begin 
    if(power_on_rst_i) begin  
        eqbk_apb_write      <= 1'b0;
        eqbk_apb_sel        <= 1'b0;
        eqbk_apb_wdata      <= 32'd0;
        eqbk_apb_addr       <= 32'd0;
        eqbk_apb_pstrobe    <= 4'd0;         
    end
    else if(eqbk_timeout_cnt == 3 & !eqbk_apb_mask) begin 
        eqbk_apb_write      <= 1'b1;
        eqbk_apb_sel        <= 1'b1;    
        eqbk_apb_addr       <= eqbk_apb_addr_tmp;               
        eqbk_apb_wdata      <= eqbk_apb_wdata_tmp;  
        eqbk_apb_pstrobe    <= 4'hf; 
    end 
    else if(slave_apb4_pready_in) begin 
        eqbk_apb_write      <= eqbk_apb_write;
        eqbk_apb_sel        <= 1'b0; 
        eqbk_apb_addr       <= eqbk_apb_addr;
        eqbk_apb_wdata      <= eqbk_apb_wdata;        
        eqbk_apb_pstrobe    <= 4'h0;                     
            
        if(rx0_eqbk_work | rx1_eqbk_work | rx2_eqbk_work | rx3_eqbk_work) begin 
            $display("apb write address: %h data: %h at time %t", eqbk_apb_addr_tmp, eqbk_apb_wdata_tmp, $time);     
        end 
    end
end     
    
always @ (posedge apb4_pclk_in or posedge power_on_rst_i) begin 
    if(power_on_rst_i) begin  
        eqbk_apb_enable     <= 1'b0;          
    end
    else if(eqbk_timeout_cnt == 4 & !eqbk_apb_mask) begin 
        eqbk_apb_enable     <= 1'b1;
    end 
    else if(slave_apb4_pready_in) begin 
        eqbk_apb_enable     <= 1'b0;                         
    end
end 

always @ (posedge apb4_pclk_in or posedge power_on_rst_i) begin 
    if(power_on_rst_i) begin  
        rx0_eqbk_work_ff1     <= 1'b0;          
    end
    else begin 
        // rx0_eqbk_work_ff1     <= rx0_eqbk_work || (cur_state == EQBK_RX0_DONE); 
        rx0_eqbk_work_ff1     <= rx0_eqbk_work || (cur_state == EQBK_RX0_DONE) || (cur_state == EQBK_RX0_DONE1);                         
    end    
end 

always @ (posedge apb4_pclk_in or posedge power_on_rst_i) begin 
    if(power_on_rst_i) begin  
        rx1_eqbk_work_ff1     <= 1'b0;          
    end
    else begin 
        rx1_eqbk_work_ff1     <= rx1_eqbk_work || (cur_state == EQBK_RX1_DONE) || (cur_state == EQBK_RX1_DONE1);                         
    end    
end 

always @ (posedge apb4_pclk_in or posedge power_on_rst_i) begin 
    if(power_on_rst_i) begin  
        rx2_eqbk_work_ff1     <= 1'b0;          
    end
    else begin 
        rx2_eqbk_work_ff1     <= rx2_eqbk_work || (cur_state == EQBK_RX2_DONE) || (cur_state == EQBK_RX2_DONE1);                         
    end    
end 

always @ (posedge apb4_pclk_in or posedge power_on_rst_i) begin 
    if(power_on_rst_i) begin  
        rx3_eqbk_work_ff1     <= 1'b0;          
    end
    else begin 
        rx3_eqbk_work_ff1     <= rx3_eqbk_work || (cur_state == EQBK_RX3_DONE) || (cur_state == EQBK_RX3_DONE1);                         
    end    
end 

///----------------------------------------------------------------------------------------------------------
 
assign  apb4_paddr_out_tmp      =   (csr_load_work_ff2 == 1'b1) ? apb_addr : 
                                    (tx0_fir_work | tx1_fir_work | tx2_fir_work | tx3_fir_work) ? fir_apb_addr : 
                                    (rx0_eqbk_work_ff1 | rx1_eqbk_work_ff1 | rx2_eqbk_work_ff1 | rx3_eqbk_work_ff1) ? eqbk_apb_addr : master_apb4_paddr_in; 

assign  slave_apb4_paddr_out    =   (apb4_paddr_out_tmp[31:23] == 9'h1) ? apb4_paddr_out_tmp : 
                                    {8'd0,(apb4_paddr_out_tmp[31:24] >> 1),apb4_paddr_out_tmp[15:0]};
                               
assign  slave_apb4_penable_out  =   (csr_load_work_ff2 == 1'b1) ? apb_enable :
                                    (tx0_fir_work | tx1_fir_work | tx2_fir_work | tx3_fir_work) ? fir_apb_enable :
                                    (rx0_eqbk_work_ff1 | rx1_eqbk_work_ff1 | rx2_eqbk_work_ff1 | rx3_eqbk_work_ff1) ? eqbk_apb_enable : master_apb4_penable_in;                                   
                                                                    
assign  slave_apb4_pprot_out    =   (csr_load_work_ff2 == 1'b1) ? 3'd0 : 
                                    (tx0_fir_work | tx1_fir_work | tx2_fir_work | tx3_fir_work) ? 3'd0 :
                                    (rx0_eqbk_work_ff1 | rx1_eqbk_work_ff1 | rx2_eqbk_work_ff1 | rx3_eqbk_work_ff1) ?  3'd0 : master_apb4_pprot_in;  
                                                                                                        
assign  slave_apb4_psel_out     =   (csr_load_work_ff2 == 1'b1) ? apb_sel : 
                                    (tx0_fir_work | tx1_fir_work | tx2_fir_work | tx3_fir_work) ? fir_apb_sel :
                                    (rx0_eqbk_work_ff1 | rx1_eqbk_work_ff1 | rx2_eqbk_work_ff1 | rx3_eqbk_work_ff1) ? eqbk_apb_sel : master_apb4_psel_in;           
        
assign  slave_apb4_pstrobe_out  =   (csr_load_work_ff2 == 1'b1) ? apb_pstrobe : 
                                    (tx0_fir_work | tx1_fir_work | tx2_fir_work | tx3_fir_work) ? fir_apb_pstrobe :
                                    (rx0_eqbk_work_ff1 | rx1_eqbk_work_ff1 | rx2_eqbk_work_ff1 | rx3_eqbk_work_ff1) ? eqbk_apb_pstrobe : master_apb4_pstrobe_in;    
    
assign  slave_apb4_pwdata_out   =   (csr_load_work_ff2 == 1'b1) ? apb_wdata :
                                    (tx0_fir_work | tx1_fir_work | tx2_fir_work | tx3_fir_work) ? fir_apb_wdata : 
                                    (rx0_eqbk_work_ff1 | rx1_eqbk_work_ff1 | rx2_eqbk_work_ff1 | rx3_eqbk_work_ff1) ? eqbk_apb_wdata : master_apb4_pwdata_in;    
        
assign  slave_apb4_pwrite_out   =   (csr_load_work_ff2 == 1'b1) ? apb_write :
                                    (tx0_fir_work | tx1_fir_work | tx2_fir_work | tx3_fir_work) ? fir_apb_write : 
                                    (rx0_eqbk_work_ff1 | rx1_eqbk_work_ff1 | rx2_eqbk_work_ff1 | rx3_eqbk_work_ff1) ? eqbk_apb_write : master_apb4_pwrite_in;           

//assign    apb4_paddr_out_tmp      =   (csr_load_work_ff2 == 1'b1) ? apb_addr : master_apb4_paddr_in;
//assign    slave_apb4_paddr_out    =   (apb4_paddr_out_tmp[23] == 1'b1) ? apb4_paddr_out_tmp : {8'd0,(apb4_paddr_out_tmp[31:24] >> 1),apb4_paddr_out_tmp[15:0]};                             
//assign    slave_apb4_penable_out  =   (csr_load_work_ff2 == 1'b1) ? apb_enable : master_apb4_penable_in;                                                                                                       
//assign    slave_apb4_pprot_out    =   (csr_load_work_ff2 == 1'b1) ? 3'd0 : master_apb4_pprot_in;                                                                                                          
//assign    slave_apb4_psel_out     =   (csr_load_work_ff2 == 1'b1) ? apb_sel : master_apb4_psel_in;                    
//assign    slave_apb4_pstrobe_out  =   (csr_load_work_ff2 == 1'b1) ? apb_pstrobe : master_apb4_pstrobe_in;     
//assign    slave_apb4_pwdata_out   =   (csr_load_work_ff2 == 1'b1) ? apb_wdata : master_apb4_pwdata_in;            
//assign    slave_apb4_pwrite_out   =   (csr_load_work_ff2 == 1'b1) ? apb_write : master_apb4_pwrite_in;    
    
assign  master_apb4_prdata_out  = slave_apb4_prdata_in ;
assign  master_apb4_pready_out  = slave_apb4_pready_in ;
assign  master_apb4_pslverr_out = slave_apb4_pslverr_in;
               
///----------------------------------------------------------------------------------------------------------

endmodule 

